create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BELOS_VORGANG_1 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	BELOS_VORGANG_ID NUMBER(38,0) NOT NULL COMMENT 'Im DWH generierte eindeutige ID für die Belos Vorgänge. Ein Belos Vorgang setzt sich aus einem Transportauftrag_1 (Logistikdaten) und einer Sendung (Abrechnungsdaten).',
	KOMPLETTLIEFERUNG_FG NUMBER(38,0) NOT NULL COMMENT 'Das Flag kennzeichnet ob der Belos Vorgang komplett geliefert wurde',
	LOESCH_FG NUMBER(38,0) NOT NULL COMMENT 'Das Flag kennzeichnet den Belos Vorgang als geloescht (1 = geloescht)',
	IN_TIME_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichen ob alle zu diesem Belos Vorgang gehörigen Positionen fristgerecht geliefert wurden',
	AV_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichen ob mindestens eine_1 zu diesem Belos Vorgang gehörige Position annahmeverweitert wurde',
	SAMMEL_LADUNG_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichen ob es sich bei der Ladung um einen Sammeltransport oder einen direkten Transport handelt (Sammelladung = 1)',
	NB_ID NUMBER(38,0) COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	SENDUNG_GEW_EINH_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Gewichtseinheit, z.Bsp. KG',
	SENDUNG_VOL_EINH_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Volumeneinheit, z.Bsp. CDM',
	DAT_LEISTUNG DATE NOT NULL COMMENT 'Datum der Leistungserstellung - Erstelldatum des Transportauftrags',
	DAT_ZUSTELLUNG DATE NOT NULL COMMENT 'avisiertes Lieferdatum',
	SENDUNG_ID NUMBER(38,0) NOT NULL COMMENT 'Fachschlüssel der referenzierten Belos Sendung die diesem Vorgang zugeodnet ist',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk/Betrieb eindeutig. Aus lgort ',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner - ID (Lieferanten - ID). Hier der Hauptlieferant (Kreditor_1)',
	GEWICHT_SENDUNG NUMBER(9,3) NOT NULL COMMENT 'Abrechnungsrelevantes Gewicht der Sendung;',
	ZUSTELLART_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Kennzeichen fuer die Arten der Zustellung eines Belos Vorgangs (z. B. Kosten und Fracht, frei Haus verzollt)',
	BELOS_VORGANGART_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Kennzeichen für die Art_1 des Belos Vorgangs (z. B. Beschaffung, Annahmeverweigerung)',
	TRANSPORTAUFTRAG_ID VARCHAR(30) NOT NULL COLLATE 'en-ci' COMMENT 'Fachschluessel des referenzierten BELOS Transportauftrags der diesem Vorgang zugeodnet ist.',
	SONDERABWICKLUNG_ID VARCHAR(20) NOT NULL COLLATE 'en-ci' COMMENT 'Kennzeichen für die Sonderabwicklung eines Belos Vorgangs (z. B. Gekühlt, Tiko) - Feld enthält Bezeichnung! Compress (''GK'',''UGK'')',
	BELOS_ADRESSE_ABSENDER_NUM_ID NUMBER(38,0) NOT NULL COMMENT 'numerischer Wert für die belos_adresse. Bei Märkten/Lägern ist hier die wup_id hinterlegt, ansonsten ein negativer Wert. Wird für Join-Zwecke benötigt',
	BELOS_ADRESSE_ABHOLUNG_ID VARCHAR(40) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
	BELOS_ADRESSE_EMPFAENGER_ID VARCHAR(40) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
	BELOS_ADRESSE_SPEDITION_ID VARCHAR(40) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
	VOL_STAURAUM NUMBER(18,3) NOT NULL COMMENT 'Abrechnungsrelevantes Volumen des erforderlichen Stauraums der Sendung',
	DEBITOR_ID NUMBER(18,0) NOT NULL COMMENT 'Debintorennummer des Absenders /Empfängers.',
	ANZ_UNTERVERPACKUNG NUMBER(9,3) COMMENT 'Anzahl der Unterverpackungen',
	UNTERVERPACKUNG_MENGE_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Mengeneinheit der Unterverpackung',
	LAGERNUMMER_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'ID der Lagernummer - höchste Ebene der Lagerhierarchie',
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	TOUR_ID NUMBER(18,0) COMMENT 'Nummer des Transportes (Tour_1)',
	BELOSART_FG NUMBER(38,0) NOT NULL COMMENT 'Zeigt an, ob es sich bei dem Vorgang um einen Distributions- oder Beschaffungsvorgang handelt',
	LEERGUT_ABH_FG NUMBER(38,0) NOT NULL COMMENT 'Flag für Leergutabholung',
	RETOUREN_FG NUMBER(38,0) NOT NULL COMMENT 'Retouren Flag',
	INDUSTRIE_ABH_FG NUMBER(38,0) NOT NULL COMMENT 'Industrie Abholung Flag',
	ANZ_STELLPLATZ NUMBER(9,2) COMMENT 'Anzahl der Stellplätze aus SAP',
	ANZ_KOLLI NUMBER(9,2) COMMENT 'Anzahl der Kollis',
	BELOS_SENDUNGSSTATUS_ID NUMBER(38,0) NOT NULL DEFAULT 3 COMMENT 'referenziert auf die Lookup-Tabelle l_belos_tourstatus_1! Es werden nur die Ausprägungen 2 und 3 benutzt',
	RUNDLAUF_TRANSPORT_FG NUMBER(38,0) NOT NULL COMMENT 'gesetzt bei Touren, die mehr als ein Ziel anfahren. Redundant zu tour_1, muss hier gespeichert werden, da belos_vorgang_1-Daten zeitlich vor tour_1-Daten geliefert werden.',
	FLEISCHWERK_FG NUMBER(38,0) NOT NULL COMMENT 'zeigt an, ob innerhalb der Tour_1 ein Fleischwerk beliefert wurde. Redundant zu tour_1, muss hier gespeichert werden, da belos_vorgang_1-Daten zeitlich vor tour_1-Daten geliefert werden.',
	DISTRIBUTION_ABR_FG NUMBER(38,0) NOT NULL COMMENT 'zeigt einen abrechnungsrelevanten Vorgang an. Redundant zu tour_1, muss hier gespeichert werden, da belos_vorgang_1-Daten zeitlich vor tour_1-Daten geliefert werden.',
	BRTGEW_SENDUNG NUMBER(18,3) COMMENT 'Abrechnungsrelevantes Brutto-Gewicht der Sendung;',
	BRTVOL_STAURAUM NUMBER(18,3) NOT NULL COMMENT 'Abrechnungsrelevantes Brutto-Volumen des erforderlichen Stauraums der Sendung',
	ANZ_STELLPLATZ_BELOS NUMBER(9,2) COMMENT 'Anzahl der Stellplätze aus dem Belos-System',
	K_NA_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag steht für Kaufland-nur Abrechnung. Für Transportprozesse, die in Regie des Dienstleisters durchgeführt werden. Flag wird gesetzt, wenn das Referenzfeld der SST mit CU beginnt',
	BELOS_AUFTRAG_ID_EXTERN VARCHAR(40) COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Auftragsnummer Warenlieferant aus der Quelle Referenz1 (Beginnt in der Quelle mit CU%)',
	BELOS_LIEFERSCHEIN_ID VARCHAR(40) COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse Lieferscheinnummer aus deem Quellfeld Referenz2. ',
	BELOS_SENDUNG_ID_EXTERN VARCHAR(40) COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Sendungsnummer Dienstleister aus dem Quellfeld Referenz4. Beginnt im Quellfeld mit SU%',
	BELOS_BESTELL_BELEG_ID_EXTERN VARCHAR(40) COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Bestellbelegnummerr aus dem Quellfeld Referenz3. Beginnt im Quellfeld mit PO%',
	MANDANT_ID_DEBITOR NUMBER(38,0) NOT NULL DEFAULT 1 COMMENT 'Mandant_ID zur Eindeutigkeit des Debitors (bisher nur DE =1 / 04.06.2016)',
	REFERENZ VARCHAR(255) COLLATE 'en-ci' COMMENT 'Sonstige Eingaben Feld Referenznummer (enthält Referenz aus SST nde_sendung ohne PO (ab Oktober 2018 befüllt, davor null) - beschränkt auf 200 Zeichen)',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	DATZEIT_SENDUNG_OFFEN TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Sendung offen\""',
	DATZEIT_WARE_VERSANDBEREIT TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Ware versandbereit\""',
	DATZEIT_SENDUNG_BEAUFTRAGT TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Sendung beauftragt\""',
	DATZEIT_SYSTEM_ZUGESTELLT TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Systemstatus zugestellt\""',
	DATZEIT_ABHOLUNG_BIS TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Abholtermin (bis)\"".',
	DATZEIT_ZUSTELLUNG_BIS TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt \""Zustelltermin (bis)\"".',
	constraint PK_BELOS_VORGANG primary key (MANDANT_ID, BELOS_VORGANG_ID)
)COMMENT='LIS - Der Belos Vorgang setzt sich aus dem Transportauftrag_1 (mit den Logistikdaten) und den Sendungsinformationen (mit den Abrechnungsdaten) zusammen.'
;
